<?php namespace ProcessWire;

/** Seafile-inspired administrative workspace for Files. */
class ProcessFiles extends Process {
	public function init(): void {
		parent::init();
		$version = Files::VERSION . '-' . (int)@filemtime(__DIR__ . '/assets/files-admin.css');
		$this->wire('config')->styles->add($this->wire('config')->urls->Files . 'assets/files-admin.css?v=' . $version);
		$scriptVersion = Files::VERSION . '-' . (int)@filemtime(__DIR__ . '/assets/files-admin.js');
		$this->wire('config')->scripts->add($this->wire('config')->urls->Files . 'assets/files-admin.js?v=' . $scriptVersion);
	}

	public static function getModuleInfo(): array {
		return [
			'title' => 'Files',
			'summary' => 'Browse private folders and manage file or folder shares.',
			'version' => 101,
			'author' => 'Maxim Semenov',
			'icon' => 'folder-open',
			'requires' => ['Files'],
			'permission' => Files::PERMISSION_USE,
			'page' => ['name' => 'files', 'parent' => 'setup', 'title' => 'Files'],
		];
	}

	private function service(): Files { /** @var Files $service */ $service=$this->wire('modules')->get('Files'); return $service; }

	public function ___execute(): string {
		$service=$this->service(); $input=$this->wire('input'); $sanitizer=$this->wire('sanitizer');
		$folderId=max(Files::ROOT_ID,(int)$input->get('folder')); $folder=$service->item($folderId); if(!$folder||$folder['kind']!=='folder')throw new Wire404Exception($this->_('Folder not found.'));
		$q=trim((string)$sanitizer->text((string)$input->get('q'))); $type=strtolower((string)$sanitizer->name((string)$input->get('type'))); $view=(string)$input->get('view')==='grid'?'grid':'list'; $items=$service->children($folderId,['q'=>$q,'type'=>$type]); $stats=$service->stats();
		$shareItem=[];$shareId=(int)$input->get('share');if($shareId>0&&$service->canShare()){$candidate=$service->item($shareId);$user=$this->wire('user');if($candidate&&$candidate['kind']==='file'&&(int)$candidate['parent_id']===$folderId&&($service->canManage($user)||(int)$candidate['owner_user_id']===(int)$user->id))$shareItem=$candidate;}
		$this->headline($this->_('Files'));
		$actions='';if($service->canCreateFolders())$actions.='<button class="uk-button uk-button-default FilesActionButton" type="button" uk-toggle="target: #files-new-folder"><i class="fa fa-folder-o" aria-hidden="true"></i><span>'.$this->_('New folder').'</span></button>';if($service->canUpload())$actions.='<a class="uk-button uk-button-primary FilesActionButton" href="'.$this->e($this->wire('page')->url.'upload/?folder='.$folderId).'"><i class="fa fa-upload" aria-hidden="true"></i><span>'.$this->_('Upload files').'</span></a>';
		$out=$this->nav('library').$this->breadcrumbs($service->breadcrumbs($folderId)).$this->intro($this->_('Private library'),(string)$folder['display_name'],$this->_('Folders and files stay private until you create a controlled share.'),$actions);
		if($service->canCreateFolders())$out.=$this->createFolderModal($folderId);$out.='<section class="FilesMetricGrid">'.$this->metric($this->_('Files'),(string)$stats['files'],'files-o').$this->metric($this->_('Storage'),$this->formatBytes((int)$stats['bytes']),'database').$this->metric($this->_('Folders'),(string)$stats['folders'],'folder-open').$this->metric($this->_('Active shares'),(string)$stats['active_shares'],'share-alt').'</section>';
		$clear=($q!==''||$type!=='')?'<a class="uk-button uk-button-default FilesFilterReset" href="'.$this->e($this->viewUrl($folderId,$view)).'" aria-label="'.$this->_('Clear filters').'"><i class="fa fa-times" aria-hidden="true"></i><span>'.$this->_('Clear').'</span></a>':'';
		$out.='<form class="FilesFilters" method="get"><input type="hidden" name="folder" value="'.$folderId.'"><input type="hidden" name="view" value="'.$view.'"><label class="FilesSearch"><span class="FilesSrOnly">'.$this->_('Search this folder').'</span><i class="fa fa-search" aria-hidden="true"></i><input class="uk-input" type="search" name="q" value="'.$this->e($q).'" placeholder="'.$this->_('Search by name').'" autocomplete="off"></label><label class="FilesTypeFilter"><span class="FilesSrOnly">'.$this->_('File type').'</span><select class="uk-select" name="type">'.$this->typeOptions($type).'</select></label><button class="uk-button uk-button-primary FilesFilterSubmit" type="submit"><i class="fa fa-filter" aria-hidden="true"></i><span>'.$this->_('Apply filters').'</span></button>'.$clear.'</form>';
		$out.=$this->itemTable($items,$folderId,$q!==''||$type!=='',$view,$q,$type);if($shareItem){$oneTime=(array)$this->wire('session')->get('files_share_once');$this->wire('session')->remove('files_share_once');$out.=$this->shareDialog($shareItem,$service->sharesForItem((int)$shareItem['id']),$oneTime);}
		return $this->workspace($out);
	}

	public function ___executeCreateFolder(): string {
		if(!$this->wire('input')->requestMethod('POST'))throw new Wire404Exception(); $this->wire('session')->CSRF->validate(); $parent=max(Files::ROOT_ID,(int)$this->wire('input')->post('parent_id'));
		$name=(string)($this->wire('input')->post('folder_name')?:$this->wire('input')->post('name'));
		try{$folder=$this->service()->createFolder($parent,$name);$this->wire('session')->message(sprintf($this->_('Folder “%s” created.'),(string)$folder['display_name']));}catch(\Throwable $e){$this->wire('session')->error($e->getMessage());}
		$this->wire('session')->redirect($this->wire('page')->url.'?folder='.$parent); return '';
	}

	public function ___executeUpload(): string {
		if(!$this->service()->canUpload())throw new WirePermissionException();$folderId=max(Files::ROOT_ID,(int)($this->wire('input')->requestMethod('POST')?$this->wire('input')->post('folder_id'):$this->wire('input')->get('folder'))); $folder=$this->service()->item($folderId); if(!$folder||$folder['kind']!=='folder')throw new Wire404Exception();
		$this->headline($this->_('Upload file'));
		if($this->wire('input')->requestMethod('POST')){$this->wire('session')->CSRF->validate();try{$file=$this->service()->storeUpload($_FILES['file']??[],$folderId);$this->wire('session')->message($this->_('File uploaded to private storage.'));$this->wire('session')->redirect($this->wire('page')->url.'item/?id='.(int)$file['id']);}catch(\Throwable $e){$this->wire('session')->error($e->getMessage());}}
		$service=$this->service();$extensions=preg_split('/[\s,]+/',strtolower(trim((string)$service->allowed_extensions)),-1,PREG_SPLIT_NO_EMPTY)?:[];$extensions=array_values(array_unique($extensions));sort($extensions,SORT_NATURAL);$accept=implode(',',array_map(static fn($extension)=>'.'.$extension,$extensions));$extensionLabels=array_map('strtoupper',$extensions);$visible=array_slice($extensionLabels,0,10);$pills='';foreach($visible as $extension)$pills.='<span>'.$this->e($extension).'</span>';if(count($extensionLabels)>count($visible))$pills.='<span class="FilesUploadMore">+'.(count($extensionLabels)-count($visible)).'</span>';
		$back=$folderId===Files::ROOT_ID?$this->wire('page')->url:$this->wire('page')->url.'?folder='.$folderId;
		$out=$this->nav('library').$this->breadcrumbs($service->breadcrumbs($folderId)).$this->intro($this->_('My Library'),$this->_('Upload a file'),$this->_('Add one original file to private storage. You can create a controlled share after the upload.'));
		$out.='<div class="FilesUploadLayout"><section class="FilesUploadPanel"><header><div><p class="FilesEyebrow">'.$this->_('Secure upload').'</p><h2>'.$this->_('Choose a file').'</h2><p>'.$this->_('Drop a file into the area below or browse your device. The original filename is preserved.').'</p></div><span class="FilesUploadSecure"><i class="fa fa-lock" aria-hidden="true"></i>'.$this->_('Private').'</span></header><form id="files-upload-form" method="post" enctype="multipart/form-data" data-upload-start="'.$this->e($this->wire('page')->url.'upload-start/').'" data-upload-chunk="'.$this->e($this->wire('page')->url.'upload-chunk/').'" data-upload-cancel="'.$this->e($this->wire('page')->url.'upload-cancel/').'" data-item-base="'.$this->e($this->wire('page')->url.'item/?id=').'" data-max-bytes="'.(max(1,(int)$service->max_upload_mb)*1048576).'" data-label-uploading="'.$this->e($this->_('Uploading…')).'" data-label-finishing="'.$this->e($this->_('Finishing upload…')).'" data-label-retry="'.$this->e($this->_('Connection interrupted. Retrying…')).'" data-label-complete="'.$this->e($this->_('Upload complete')).'"><input type="hidden" name="folder_id" value="'.$folderId.'"><label class="FilesDropzone" for="files-upload"><input id="files-upload" type="file" name="file" accept="'.$this->e($accept).'" required><span class="FilesDropzoneIcon"><i class="fa fa-cloud-upload" aria-hidden="true"></i></span><span class="FilesDropzoneCopy"><strong>'.$this->_('Drop your file here').'</strong><small>'.$this->_('or choose it from your device').'</small></span><span class="uk-button uk-button-default FilesBrowseButton">'.$this->_('Browse files').'</span></label><div id="files-selected-file" class="FilesSelectedFile" hidden aria-live="polite"><span><i class="fa fa-file-o" aria-hidden="true"></i></span><div><strong id="files-selected-name"></strong><small id="files-selected-size"></small></div><button id="files-remove-selection" type="button" aria-label="'.$this->_('Remove selected file').'" title="'.$this->_('Remove selected file').'"><i class="fa fa-times" aria-hidden="true"></i></button></div><div id="files-upload-progress" class="FilesUploadProgress" hidden aria-live="polite"><div><strong id="files-upload-status">'.$this->_('Preparing upload…').'</strong><span id="files-upload-percent">0%</span></div><progress id="files-upload-meter" max="100" value="0">0%</progress><small>'.$this->_('Large files are transferred securely in retryable chunks. Keep this page open until the upload completes.').'</small></div><div id="files-upload-error" class="FilesUploadError" role="alert" hidden></div>'.$this->csrfFields().'<div class="FilesUploadFooter"><a class="uk-button uk-button-default" href="'.$this->e($back).'">'.$this->_('Cancel').'</a><button id="files-upload-submit" class="uk-button uk-button-primary" type="submit"><i class="fa fa-upload" aria-hidden="true"></i><span>'.$this->_('Upload file').'</span></button></div></form></section><aside class="FilesUploadSidebar"><section class="FilesUploadInfo"><span class="FilesUploadInfoIcon"><i class="fa fa-folder-open" aria-hidden="true"></i></span><div><small>'.$this->_('Destination').'</small><strong>'.$this->e((string)$folder['display_name']).'</strong></div></section><section class="FilesUploadInfo"><span class="FilesUploadInfoIcon"><i class="fa fa-balance-scale" aria-hidden="true"></i></span><div><small>'.$this->_('Maximum file size').'</small><strong>'.(int)$service->max_upload_mb.' MB</strong><p>'.sprintf($this->_('Large files are split into server-safe chunks of up to %s.'),$this->formatBytes($service->chunkUploadSize())).'</p></div></section><section class="FilesUploadRules"><h3><i class="fa fa-file-text-o" aria-hidden="true"></i>'.$this->_('Allowed file types').'</h3><div class="FilesUploadPills">'.$pills.'</div><p>'.sprintf($this->_n('%d configured extension','%d configured extensions',count($extensionLabels)),count($extensionLabels)).'</p></section><section class="FilesUploadPrivacy"><i class="fa fa-shield" aria-hidden="true"></i><div><strong>'.$this->_('Private by default').'</strong><p>'.$this->_('Uploaded bytes stay outside the public web root until you explicitly create a sharing link.').'</p></div></section></aside></div>';
		return $this->workspace($out);
	}

	public function ___executeUploadStart(): string { if(!$this->wire('input')->requestMethod('POST'))throw new Wire404Exception();try{$this->wire('session')->CSRF->validate();$session=$this->service()->beginChunkedUpload((string)$this->wire('input')->post('file_name'),(int)$this->wire('input')->post('file_size'),max(Files::ROOT_ID,(int)$this->wire('input')->post('folder_id')));$this->jsonResponse(['ok'=>true]+$session);}catch(\Throwable $e){$this->jsonResponse(['ok'=>false,'error'=>$e->getMessage()],$e instanceof WirePermissionException?403:400);} }
	public function ___executeUploadChunk(): string { if(!$this->wire('input')->requestMethod('POST'))throw new Wire404Exception();try{$this->wire('session')->CSRF->validate();$result=$this->service()->appendChunkedUpload((string)$this->wire('input')->post('upload_id'),(int)$this->wire('input')->post('offset'),$_FILES['chunk']??[]);if(!empty($result['complete'])){$result['item_id']=(int)$result['item']['id'];$result['item_url']=$this->wire('page')->url.'item/?id='.$result['item_id'];unset($result['item']);}$this->jsonResponse(['ok'=>true]+$result);}catch(\Throwable $e){$this->jsonResponse(['ok'=>false,'error'=>$e->getMessage()],$e instanceof WirePermissionException?403:400);} }
	public function ___executeUploadCancel(): string { if(!$this->wire('input')->requestMethod('POST'))throw new Wire404Exception();try{$this->wire('session')->CSRF->validate();if(!$this->service()->cancelChunkedUpload((string)$this->wire('input')->post('upload_id')))throw new WireException($this->_('The temporary upload could not be removed.'));$this->jsonResponse(['ok'=>true]);}catch(\Throwable $e){$this->jsonResponse(['ok'=>false,'error'=>$e->getMessage()],$e instanceof WirePermissionException?403:400);} }

	public function ___executeItem(): string {
		$id=(int)$this->wire('input')->get('id');$service=$this->service();$item=$service->item($id);$user=$this->wire('user');if(!$item||(!$service->canManage($user)&&(int)$item['owner_user_id']!==(int)$user->id))throw new Wire404Exception();$this->headline((string)$item['display_name']);$oneTime=(array)$this->wire('session')->get('files_share_once');$this->wire('session')->remove('files_share_once');
		$folder=$item['kind']==='folder';$actions='';if(!$folder&&$service->canDownload())$actions.='<a class="uk-button uk-button-default FilesActionButton" href="'.$this->e($this->wire('page')->url.'download/?id='.$id).'"><i class="fa fa-download" aria-hidden="true"></i><span>'.$this->_('Download').'</span></a>';if($service->canShare())$actions.='<a class="uk-button uk-button-primary FilesActionButton" href="#files-create-share"><i class="fa fa-share-alt" aria-hidden="true"></i><span>'.$this->_('Create share').'</span></a>';
		$out=$this->nav('library').$this->breadcrumbs($this->service()->breadcrumbs($id)).$this->intro($folder?$this->_('Folder details'):$this->_('File details'),(string)$item['display_name'],$folder?$this->_('Inspect this folder and create controlled access to its live subtree.'):$this->_('Inspect the original file, download it, and control every sharing link.'),$actions);
		if(!empty($oneTime['url'])&&(int)($oneTime['item_id']??0)===$id)$out.='<section class="FilesShareOnce"><p class="uk-text-meta uk-text-uppercase uk-margin-remove">'.$this->_('New link').'</p><h2>'.$this->_('Sharing link created').'</h2><p>'.$this->_('The secret is encrypted at rest and remains available to authorized owners.').'</p><div><input class="uk-input" readonly value="'.$this->e($oneTime['url']).'" onclick="this.select()"><button class="uk-button uk-button-primary" type="button" onclick="navigator.clipboard.writeText(this.previousElementSibling.value);this.textContent=\''.$this->_('Copied').'\'">'.$this->_('Copy').'</button></div></section>';
		if(!$folder&&$service->canDownload())$out.=$this->previewPanel($item);
		$out.='<div class="FilesDetailGrid">'.$this->metadataPanel($item).($service->canShare()?$this->shareForm($item):'').'</div>';if($service->canShare()){$shares=$service->sharesForItem($id);$out.=$this->shareTable($shares,$id);}
		if($item['kind']==='file'&&$service->canDelete())$out.='<details class="FilesDanger"><summary>'.$this->_('Delete file').'</summary><p>'.$this->_('This permanently removes the stored bytes and every share.').'</p><form method="post" action="'.$this->e($this->wire('page')->url.'delete/').'" onsubmit="return confirm(\''.$this->e($this->_('Delete this file permanently?')).'\')"><input type="hidden" name="id" value="'.$id.'">'.$this->csrfFields().'<button class="uk-button uk-button-danger" type="submit">'.$this->_('Delete permanently').'</button></form></details>';
		return $this->workspace($out);
	}

	public function ___executeShare(): string {
		if(!$this->wire('input')->requestMethod('POST'))throw new Wire404Exception();$this->wire('session')->CSRF->validate();$id=(int)$this->wire('input')->post('id');
		try{$share=$this->service()->createShare($id,['days'=>(int)$this->wire('input')->post('days'),'max_downloads'=>(int)$this->wire('input')->post('max_downloads'),'password'=>(string)$this->wire('input')->post('password'),'recipient_user_id'=>(int)$this->wire('input')->post('recipient_user_id')]);$this->wire('session')->set('files_share_once',['item_id'=>$id,'url'=>$share['url'],'direct_url'=>$share['direct_url']]);$this->wire('session')->message($this->_('Sharing link created.'));}catch(\Throwable $e){$this->wire('session')->error($e->getMessage());}
		$item=$this->service()->item($id);$dialog=(string)$this->wire('input')->post('return_to')==='dialog'&&$item;$target=$dialog?$this->wire('page')->url.'?folder='.(int)$item['parent_id'].'&share='.$id:$this->wire('page')->url.'item/?id='.$id;$this->wire('session')->redirect($target);return '';
	}

	public function ___executeRevoke(): string { if(!$this->wire('input')->requestMethod('POST'))throw new Wire404Exception();$this->wire('session')->CSRF->validate();$id=(int)$this->wire('input')->post('id');$item=(int)$this->wire('input')->post('item_id');$this->service()->revokeShare($id);$this->wire('session')->message($this->_('Sharing link deleted.'));$stored=$this->service()->item($item);$dialog=(string)$this->wire('input')->post('return_to')==='dialog'&&$stored;$target=$dialog?$this->wire('page')->url.'?folder='.(int)$stored['parent_id'].'&share='.$item:$this->wire('page')->url.'item/?id='.$item;$this->wire('session')->redirect($target);return ''; }
	public function ___executeDelete(): string { if(!$this->wire('input')->requestMethod('POST'))throw new Wire404Exception();$this->wire('session')->CSRF->validate();$id=(int)$this->wire('input')->post('id');$item=$this->service()->item($id);$parent=(int)($item['parent_id']??Files::ROOT_ID);$this->service()->deleteFile($id);$this->wire('session')->message($this->_('File permanently deleted.'));$this->wire('session')->redirect($this->wire('page')->url.'?folder='.$parent);return ''; }
	public function ___executeDownload(): string { $item=$this->service()->item((int)$this->wire('input')->get('id'));if(!$item||$item['kind']!=='file')throw new Wire404Exception();$this->service()->streamManagedFile($item);return ''; }
	public function ___executePreview(): string { $this->service()->streamManagedPreview((int)$this->wire('input')->get('id'));return ''; }

	public function ___executeShared(): string {
		$this->headline($this->_('Shared with me'));$shareId=(int)$this->wire('input')->get('id');$out=$this->nav('shared').$this->intro($this->_('Incoming access'),$this->_('Shared with me'),$this->_('Items explicitly assigned to your ProcessWire account.'));
		if($shareId>0){$content=$this->service()->sharedContent($shareId);$out.=$this->sharedContentTable($content);}
		else{$items=$this->service()->sharedWithUser();$out.=$this->sharedRootTable($items);}
		return $this->workspace($out);
	}

	public function ___executeSharedDownload(): string { $this->service()->streamSharedFile((int)$this->wire('input')->get('share'),(int)$this->wire('input')->get('file'));return ''; }

	private function nav(string $active): string { $base=$this->wire('page')->url;$settings=$this->wire('config')->urls->admin.'module/edit?name=Files&collapse_info=1';$items=['library'=>[$base,$this->_('My Library'),'folder-open'], 'shared'=>[$base.'shared/',$this->_('Shared with me'),'users']];$out='<div class="FilesNavigation"><nav aria-label="'.$this->_('Files sections').'"><ul class="uk-subnav uk-subnav-pill">';foreach($items as $key=>[$url,$label,$icon])$out.='<li'.($active===$key?' class="uk-active"':'').'><a href="'.$this->e($url).'"'.($active===$key?' aria-current="page"':'').'><i class="fa fa-'.$icon.'" aria-hidden="true"></i><span>'.$this->e($label).'</span></a></li>';$settingsLink=$this->service()->canManage()?'<a class="FilesSettings" href="'.$this->e($settings).'"><i class="fa fa-cog" aria-hidden="true"></i><span>'.$this->_('Settings').'</span></a>':'';return$out.'</ul></nav>'.$settingsLink.'</div>'; }
	private function breadcrumbs(array $items): string { $out='<nav class="FilesBreadcrumbs" aria-label="'.$this->_('Folder path').'"><i class="fa fa-sitemap FilesBreadcrumbIcon" aria-hidden="true"></i>';foreach($items as $index=>$item){if($index)$out.='<i class="fa fa-angle-right FilesBreadcrumbSeparator" aria-hidden="true"></i>';$url=$item['id']==Files::ROOT_ID?$this->wire('page')->url:$this->wire('page')->url.'?folder='.(int)$item['id'];$out.=$index===count($items)-1?'<span aria-current="page">'.$this->e($item['display_name']).'</span>':'<a href="'.$this->e($url).'">'.$this->e($item['display_name']).'</a>'; }return$out.'</nav>'; }
	private function intro(string $eyebrow,string $title,string $description,string $actions=''): string { return'<section class="FilesIntro"><div><p class="FilesEyebrow">'.$this->e($eyebrow).'</p><h2>'.$this->e($title).'</h2><p>'.$this->e($description).'</p></div>'.($actions?'<div class="FilesActions">'.$actions.'</div>':'').'</section>'; }
	private function metric(string $label,string $value,string $icon): string { return'<article class="FilesMetric"><span><i class="fa fa-'.$this->e($icon).'"></i></span><div><small>'.$this->e($label).'</small><strong>'.$this->e($value).'</strong></div></article>'; }

	private function itemTable(array $items,int $folderId,bool $filtered=false,string $view='list',string $q='',string $type=''): string {
		$count=count($items);$summary=sprintf($this->_n('%d item','%d items',$count),$count);$listUrl=$this->viewUrl($folderId,'list',$q,$type);$gridUrl=$this->viewUrl($folderId,'grid',$q,$type);
		$toggle='<nav class="FilesViewToggle" aria-label="'.$this->_('Display mode').'"><a href="'.$this->e($listUrl).'" class="'.($view==='list'?'is-active':'').'"'.($view==='list'?' aria-current="page"':'').' title="'.$this->_('List view').'"><i class="fa fa-list" aria-hidden="true"></i><span class="FilesSrOnly">'.$this->_('List view').'</span></a><a href="'.$this->e($gridUrl).'" class="'.($view==='grid'?'is-active':'').'"'.($view==='grid'?' aria-current="page"':'').' title="'.$this->_('Grid view').'"><i class="fa fa-th-large" aria-hidden="true"></i><span class="FilesSrOnly">'.$this->_('Grid view').'</span></a></nav>';
		$out='<section class="FilesTable" data-view="'.$view.'"><header><div><p class="FilesEyebrow">'.$this->_('Contents').'</p><h2>'.$this->e($summary).'</h2></div><div class="FilesTableTools"><span class="FilesTableHint"><i class="fa fa-lock" aria-hidden="true"></i>'.$this->_('Private by default').'</span>'.$toggle.'</div></header>';
		if(!$items){$title=$filtered?$this->_('No matching items'):$this->_('This folder is empty');$text=$filtered?$this->_('Try another name or file type, or clear the current filters.'):$this->_('Create a subfolder or upload the first file.');$action=$filtered?'<a class="uk-button uk-button-default" href="'.$this->e($this->viewUrl($folderId,$view)).'">'.$this->_('Clear filters').'</a>':'';return$out.'<div class="FilesEmpty"><span class="FilesEmptyIcon"><i class="fa fa-'.($filtered?'search':'folder-open-o').'" aria-hidden="true"></i></span><h3>'.$title.'</h3><p>'.$text.'</p>'.$action.'</div></section>';}
		if($view==='grid') {
			$out.='<div class="FilesGrid" role="list">';
			foreach($items as $item){[$open,$share]=$this->itemUrls($item,$folderId,$view,$q,$type);$folder=$item['kind']==='folder';$meta=$folder?$this->_('Folder'):strtoupper($this->e($item['extension'])).' · '.$this->e($this->formatBytes((int)$item['size_bytes']));$out.='<article class="FilesGridItem" role="listitem"><a class="FilesGridItemMain" href="'.$this->e($open).'"><span class="FilesGridIcon"><i class="fa fa-'.($folder?'folder':'file-o').'" aria-hidden="true"></i></span><span><strong>'.$this->e($item['display_name']).'</strong><small>'.$meta.'</small></span></a><div class="FilesGridMeta"><time datetime="'.$this->e((string)$item['updated_at']).'"><i class="fa fa-clock-o" aria-hidden="true"></i>'.$this->e($this->formatDate((string)$item['updated_at'])).'</time></div><footer><div class="FilesRowActions">'.$this->itemActionLinks($item,$open,$share).'</div></footer></article>';}
			return$out.'</div></section>';
		}
		$out.='<div class="FilesTableScroll"><table class="uk-table uk-table-divider uk-table-hover uk-table-middle"><thead><tr><th>'.$this->_('Name').'</th><th>'.$this->_('Size').'</th><th>'.$this->_('Updated').'</th><th class="FilesActionsColumn">'.$this->_('Actions').'</th></tr></thead><tbody>';
		foreach($items as $item){[$open,$share]=$this->itemUrls($item,$folderId,$view,$q,$type);$folder=$item['kind']==='folder';$out.='<tr class="FilesItemRow"><td data-label="'.$this->_('Name').'"><a class="FilesItemName" href="'.$this->e($open).'"><span><i class="fa fa-'.($folder?'folder':'file-o').'" aria-hidden="true"></i></span><div><strong>'.$this->e($item['display_name']).'</strong>'.($folder?'<small>'.$this->_('Folder').'</small>':'<small>'.strtoupper($this->e($item['extension'])).' · '.$this->e((string)$item['mime_type']).'</small>').'</div></a></td><td data-label="'.$this->_('Size').'">'.($folder?'<span class="FilesMuted">—</span>':$this->e($this->formatBytes((int)$item['size_bytes']))).'</td><td data-label="'.$this->_('Updated').'"><time datetime="'.$this->e((string)$item['updated_at']).'">'.$this->e($this->formatDate((string)$item['updated_at'])).'</time></td><td data-label="'.$this->_('Actions').'"><div class="FilesRowActions">'.$this->itemActionLinks($item,$open,$share).'</div></td></tr>';}
		return$out.'</tbody></table></div></section>';
	}

	private function itemUrls(array $item,int $folderId,string $view,string $q,string $type): array { $folder=$item['kind']==='folder';$open=$folder?$this->viewUrl((int)$item['id'],$view):$this->wire('page')->url.'item/?id='.(int)$item['id'];$share=$folder?$this->wire('page')->url.'item/?id='.(int)$item['id']:$this->viewUrl($folderId,$view,$q,$type).'&share='.(int)$item['id'];return[$open,$share]; }
	private function itemActionLinks(array $item,string $open,string $share): string { $folder=$item['kind']==='folder';$actions='';if(!$folder&&$this->service()->canDownload())$actions.='<a href="'.$this->e($this->wire('page')->url.'download/?id='.(int)$item['id']).'" aria-label="'.$this->_('Download').'" title="'.$this->_('Download').'"><i class="fa fa-download" aria-hidden="true"></i><span>'.$this->_('Download').'</span></a>';if($this->service()->canShare())$actions.='<a href="'.$this->e($share).'" aria-label="'.$this->_('Share').'" title="'.$this->_('Share').'"><i class="fa fa-share-alt" aria-hidden="true"></i><span>'.$this->_('Share').'</span></a>';return$actions.'<a class="FilesRowPrimary" href="'.$this->e($open).'" aria-label="'.$this->_('Open').'" title="'.$this->_('Open').'"><span>'.$this->_('Open').'</span><i class="fa fa-angle-right" aria-hidden="true"></i></a>'; }

	private function createFolderModal(int $parent): string { return'<div id="files-new-folder" uk-modal><div class="uk-modal-dialog uk-modal-body"><button class="uk-modal-close-default" type="button" uk-close></button><h2 class="uk-modal-title">'.$this->_('New folder').'</h2><form method="post" action="'.$this->e($this->wire('page')->url.'create-folder/').'" class="uk-form-stacked" autocomplete="off" data-form-type="other"><input type="hidden" name="parent_id" value="'.$parent.'"><label class="uk-form-label" for="files-folder-name">'.$this->_('Folder name').'</label><input class="uk-input" id="files-folder-name" name="folder_name" type="text" maxlength="255" autocomplete="off" autocorrect="off" spellcheck="false" data-1p-ignore data-lpignore="true" aria-describedby="files-folder-name-note" required autofocus><p id="files-folder-name-note" class="FilesFieldNote">'.$this->_('Enter a unique name for this location.').'</p>'.$this->csrfFields().'<div class="uk-text-right uk-margin-top"><button class="uk-button uk-button-default uk-modal-close" type="button">'.$this->_('Cancel').'</button> <button class="uk-button uk-button-primary" type="submit">'.$this->_('Create').'</button></div></form></div></div>'; }
	private function shareDialog(array $item,array $shares,array $oneTime): string {
		$id=(int)$item['id'];$new=!empty($oneTime['url'])&&(int)($oneTime['item_id']??0)===$id;$internal=rtrim((string)$this->wire('config')->urls->httpRoot,'/').$this->wire('page')->url.'item/?id='.$id;
		$newBlock=$new?'<div class="FilesShareCreated"><i class="fa fa-check-circle"></i><div><strong>'.$this->_('Share link created').'</strong><p>'.$this->_('You can copy it again later from this window.').'</p></div></div>'.$this->copyField($this->_('Link'),(string)$oneTime['url'],'new-link').$this->copyField($this->_('Direct download link'),(string)($oneTime['direct_url']??''),'new-direct'):'';
		$rows='';foreach($shares as $share){$expired=!empty($share['expires_at'])&&strtotime((string)$share['expires_at'])<=time();$limited=(int)$share['max_downloads']>0&&(int)$share['download_count']>=(int)$share['max_downloads'];$active=empty($share['revoked_at'])&&!$expired&&!$limited;$status=!empty($share['revoked_at'])?$this->_('Deleted'):($expired?$this->_('Expired'):($limited?$this->_('Limit reached'):$this->_('Active')));$recipient=(int)$share['recipient_user_id']>0?((string)$share['recipient_name'].' · '.(string)$share['recipient_email']):$this->_('Anyone with link');$link=(string)($share['url']??'');$direct=(string)($share['direct_url']??'');$linkCell=$link!==''?$this->copyField('', $link,'share-'.(int)$share['id'],true).'<small class="FilesDirectLabel">'.$this->_('Direct download link').'</small>'.$this->copyField('', $direct,'direct-'.(int)$share['id'],true):'<span class="FilesLegacyLink"><i class="fa fa-lock"></i> '.$this->_('Legacy link').' · …'.$this->e($share['token_hint']).'<small>'.$this->_('Its original secret cannot be recovered; generate a new link to copy it.').'</small></span>';$action=$active?'<form method="post" action="'.$this->e($this->wire('page')->url.'revoke/').'"><input type="hidden" name="id" value="'.(int)$share['id'].'"><input type="hidden" name="item_id" value="'.$id.'"><input type="hidden" name="return_to" value="dialog">'.$this->csrfFields().'<button class="FilesIconButton" type="submit" title="'.$this->_('Delete link').'" aria-label="'.$this->_('Delete link').'"><i class="fa fa-trash"></i></button></form>':'<span class="FilesBadge" data-state="neutral">'.$this->e($status).'</span>';$rows.='<tr><td>'.$linkCell.'</td><td>'.$this->e($recipient).'</td><td>'.$this->e((string)$share['expires_at']).'</td><td>'.$action.'</td></tr>';}
		if($rows==='')$rows='<tr><td colspan="4" class="FilesShareEmpty">'.$this->_('No share links yet.').'</td></tr>';
		$sharePanel=$newBlock.'<div class="FilesShareToolbar"><strong>'.$this->_('Share links').'</strong><details'.(!$shares?' open':'').'><summary class="uk-button uk-button-primary">'.$this->_('Generate link').'</summary>'.$this->dialogShareForm($item).'</details></div><div class="uk-overflow-auto"><table class="uk-table uk-table-divider uk-table-middle FilesShareList"><thead><tr><th>'.$this->_('Link').'</th><th>'.$this->_('Permission').'</th><th>'.$this->_('Expiration').'</th><th></th></tr></thead><tbody>'.$rows.'</tbody></table></div>';
		$internalPanel='<div class="FilesInternalLink"><h3>'.$this->_('Internal link').'</h3><p>'.$this->_('Use this link for authenticated Files users who already have access.').'</p>'.$this->copyField($this->_('Link'),$internal,'internal-link').'</div>';
		$message=json_encode($this->_('Share link is copied to the clipboard.'),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT);
		$script='<script>(function(){function ready(){UIkit.modal("#files-share-dialog").show();document.querySelectorAll("[data-files-copy]").forEach(function(button){button.addEventListener("click",function(){var input=document.getElementById(button.getAttribute("data-files-copy"));if(!input)return;navigator.clipboard.writeText(input.value).then(function(){UIkit.notification({message:'.$message.',status:"success",pos:"top-center"});});});});}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",ready);else ready();})();</script>';
		return'<div id="files-share-dialog" class="FilesShareDialog" uk-modal><div class="uk-modal-dialog"><button class="uk-modal-close-default" type="button" uk-close></button><header class="FilesShareHeader"><h2>'.$this->_('Share').' <strong>'.$this->e($item['display_name']).'</strong></h2></header><div class="FilesShareLayout"><ul class="FilesShareNav" uk-switcher="connect: #files-share-panels"><li class="uk-active"><a href="#">'.$this->_('Share Link').'</a></li><li><a href="#">'.$this->_('Internal Link').'</a></li></ul><ul id="files-share-panels" class="uk-switcher FilesSharePanels"><li>'.$sharePanel.'</li><li>'.$internalPanel.'</li></ul></div></div></div>'.$script;
	}
	private function dialogShareForm(array $item): string { $service=$this->service();$default=max(1,(int)$service->default_share_days);$maximum=max($default,(int)$service->max_share_days);return'<form class="FilesShareGenerate uk-form-stacked" method="post" action="'.$this->e($this->wire('page')->url.'share/').'"><input type="hidden" name="id" value="'.(int)$item['id'].'"><input type="hidden" name="return_to" value="dialog"><label class="uk-form-label" for="files-dialog-recipient">'.$this->_('Who can open it').'</label><select class="uk-select" id="files-dialog-recipient" name="recipient_user_id">'.$this->recipientOptions().'</select><div class="FilesFormGrid"><div><label class="uk-form-label" for="files-dialog-days">'.$this->_('Expires after, days').'</label><input class="uk-input" id="files-dialog-days" type="number" name="days" min="1" max="'.$maximum.'" value="'.$default.'" required></div><div><label class="uk-form-label" for="files-dialog-limit">'.$this->_('Download limit').'</label><input class="uk-input" id="files-dialog-limit" type="number" name="max_downloads" min="0" value="0"></div></div><label class="uk-form-label" for="files-dialog-password">'.$this->_('Password (optional)').'</label><input class="uk-input" id="files-dialog-password" type="password" name="password" minlength="8" autocomplete="new-password">'.$this->csrfFields().'<button class="uk-button uk-button-primary uk-margin-top" type="submit">'.$this->_('Create share link').'</button></form>'; }
	private function recipientOptions(): string { $options='<option value="0">'.$this->_('Anyone with the secret link').'</option>';foreach($this->wire('users')->find('id>0,sort=name,limit=200') as $user){if($user->isGuest()||(int)$user->id===(int)$this->wire('user')->id)continue;$label=(string)($user->get('display_name')?:$user->name);$options.='<option value="'.(int)$user->id.'">'.$this->e($label).' · '.$this->e($user->email).'</option>';}return$options; }
	private function copyField(string $label,string $url,string $key,bool $compact=false): string { if($url==='')return'';$inputId='files-copy-'.preg_replace('/[^a-z0-9-]+/i','-',$key);return'<div class="FilesCopyField'.($compact?' FilesCopyField--compact':'').'">'.($label!==''?'<label for="'.$inputId.'">'.$this->e($label).'</label>':'').'<div><input class="uk-input" id="'.$inputId.'" readonly value="'.$this->e($url).'" onclick="this.select()"><button class="uk-button uk-button-primary" type="button" data-files-copy="'.$inputId.'"><i class="fa fa-copy"></i><span>'.$this->_('Copy').'</span></button></div></div>'; }
	private function metadataPanel(array $item): string { $folder=$item['kind']==='folder';$desc=$folder?$this->service()->descendants((int)$item['id']):[];$files=$folder?count(array_filter($desc,static fn($row)=>$row['kind']==='file')):0;$folders=$folder?count($desc)-$files:0;$type=$folder?$this->_('Folder'):strtoupper($this->e($item['extension']));$detail=$folder?$this->_('Live folder tree'):$this->e($item['mime_type']);$size=$folder?sprintf($this->_('%d folders · %d files'),$folders,$files):$this->e($this->formatBytes((int)$item['size_bytes']));$sizeNote=$folder?$this->_('Current subtree'):$this->_('Original file size');$checksum=!$folder?'<div class="FilesMetadataChecksum"><dt><i class="fa fa-hashtag" aria-hidden="true"></i> SHA-256</dt><dd><code>'.$this->e($item['checksum_sha256']).'</code></dd></div>':'';return'<section class="FilesPanel FilesPropertiesPanel"><header class="FilesPanelTitle"><span class="FilesPanelIcon"><i class="fa fa-'.($folder?'folder-open':'file-o').'" aria-hidden="true"></i></span><div><p class="FilesEyebrow">'.$this->_('Properties').'</p><h2>'.$this->_('Item information').'</h2></div><span class="FilesTypeBadge">'.$type.'</span></header><dl class="FilesMetadata"><div><dt><i class="fa fa-file-o" aria-hidden="true"></i>'.$this->_('Type').'</dt><dd><strong>'.$type.'</strong><small>'.$detail.'</small></dd></div><div><dt><i class="fa fa-database" aria-hidden="true"></i>'.$this->_('Size').'</dt><dd><strong>'.$size.'</strong><small>'.$sizeNote.'</small></dd></div><div><dt><i class="fa fa-clock-o" aria-hidden="true"></i>'.$this->_('Updated').'</dt><dd><strong>'.$this->e($this->formatDate((string)$item['updated_at'])).'</strong><small>'.$this->_('Last metadata change').'</small></dd></div>'.$checksum.'</dl></section>'; }

	private function previewPanel(array $item): string {
		$kind=$this->service()->previewKind((int)$item['id']);$url=$this->wire('page')->url.'preview/?id='.(int)$item['id'];$download=$this->wire('page')->url.'download/?id='.(int)$item['id'];$name=$this->e((string)$item['display_name']);
		$labels=['image'=>$this->_('Image'),'pdf'=>$this->_('PDF document'),'text'=>$this->_('Text document'),'audio'=>$this->_('Audio'),'video'=>$this->_('Video'),'office'=>$this->_('ONLYOFFICE')];
		if($kind==='image')$content='<img src="'.$this->e($url).'" alt="'.sprintf($this->_('Preview of %s'),$name).'">';
		elseif($kind==='text'){$preview=$this->service()->previewText((int)$item['id']);$content='<pre tabindex="0">'.$this->e($preview['content']).'</pre>'.($preview['truncated']?'<p class="FilesPreviewTruncated"><i class="fa fa-info-circle" aria-hidden="true"></i>'.$this->_('Preview limited to 512 KiB. Download the file to view the rest.').'</p>':'');}
		elseif($kind==='pdf')$content='<iframe src="'.$this->e($url).'" title="'.sprintf($this->_('Preview of %s'),$name).'" loading="lazy"></iframe>';
		elseif($kind==='audio')$content='<audio controls preload="metadata" src="'.$this->e($url).'">'.$this->_('Your browser cannot play this audio file.').'</audio>';
		elseif($kind==='video')$content='<video controls preload="metadata" src="'.$this->e($url).'">'.$this->_('Your browser cannot play this video file.').'</video>';
		elseif($kind==='office'){$editor=$this->service()->onlyOfficeEditorConfig((int)$item['id']);$mount='files-onlyoffice-'.(int)$item['id'];$config=json_encode($editor['config'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_SLASHES);$error=$this->e($this->_('ONLYOFFICE could not be loaded. Check the Document Server URL and network access.'));$content='<div id="'.$mount.'" class="FilesOnlyOffice"><div class="FilesOnlyOfficeLoading"><i class="fa fa-circle-o-notch fa-spin" aria-hidden="true"></i>'.$this->_('Loading ONLYOFFICE preview…').'</div></div><script src="'.$this->e($editor['api_url']).'"></script><script>(function(){var mount=document.getElementById('.json_encode($mount).');try{if(!window.DocsAPI)throw new Error("DocsAPI unavailable");new DocsAPI.DocEditor('.json_encode($mount).','.$config.');}catch(error){mount.innerHTML='.json_encode('<div class="FilesOnlyOfficeError"><i class="fa fa-exclamation-triangle" aria-hidden="true"></i><strong>'.$error.'</strong></div>').';}})();</script>';}
		else{$office=in_array(strtolower((string)$item['extension']),['doc','docx','xls','xlsx','ppt','pptx','odt','ods','odp'],true);$settings=$this->wire('config')->urls->admin.'module/edit?name=Files&collapse_info=1#wrap_Inputfield_files_config_onlyoffice';$message=$office?$this->_('Connect an ONLYOFFICE Document Server in the module settings to preview this office document.'):$this->_('This format cannot be shown safely in the browser. Download the original file to open it in a compatible application.');$setup=$office?'<a class="uk-button uk-button-default" href="'.$this->e($settings).'"><i class="fa fa-cog" aria-hidden="true"></i> '.$this->_('Configure ONLYOFFICE').'</a>':'';$content='<div class="FilesPreviewUnavailable"><span><i class="fa fa-file-o" aria-hidden="true"></i></span><h3>'.$this->_('Preview unavailable').'</h3><p>'.$message.'</p><div>'.$setup.'<a class="uk-button uk-button-primary" href="'.$this->e($download).'"><i class="fa fa-download" aria-hidden="true"></i> '.$this->_('Download file').'</a></div></div>';}
		$open=$kind!==''&&$kind!=='office'?'<a class="uk-button uk-button-default" href="'.$this->e($url).'"><i class="fa fa-eye" aria-hidden="true"></i><span>'.$this->_('Open preview').'</span></a>':'';
		return'<section class="FilesPreview FilesPreview--'.($kind?:'unavailable').'"><header><div><p class="FilesEyebrow">'.$this->_('Preview').'</p><h2>'.$name.'</h2><p>'.$this->_('The original stays in private storage and is rendered through an authenticated, non-cacheable response.').'</p></div><div class="FilesPreviewActions">'.($kind!==''?'<span class="FilesTypeBadge">'.$labels[$kind].'</span>':'').$open.'</div></header><div class="FilesPreviewStage">'.$content.'</div></section>';
	}

	private function shareForm(array $item): string { $service=$this->service();$default=max(1,(int)$service->default_share_days);$maximum=max($default,(int)$service->max_share_days);$kind=$item['kind']==='folder'?$this->_('the folder and its live subtree'):$this->_('this file');return'<section id="files-create-share" class="FilesPanel FilesAccessPanel"><header class="FilesPanelTitle"><span class="FilesPanelIcon"><i class="fa fa-share-alt" aria-hidden="true"></i></span><div><p class="FilesEyebrow">'.$this->_('Controlled access').'</p><h2>'.$this->_('Create a share').'</h2></div></header><div class="FilesShareScope"><i class="fa fa-eye" aria-hidden="true"></i><p>'.sprintf($this->_('Creates read-only access to %s. You can revoke it at any time.'),$kind).'</p></div><form method="post" action="'.$this->e($this->wire('page')->url.'share/').'" class="uk-form-stacked"><input type="hidden" name="id" value="'.(int)$item['id'].'"><div class="FilesFormField"><label class="uk-form-label" for="files-recipient">'.$this->_('Who can open it').'</label><select class="uk-select" id="files-recipient" name="recipient_user_id">'.$this->recipientOptions().'</select><small>'.$this->_('Public links work for anyone with the secret. A selected user must sign in with that exact account.').'</small></div><div class="FilesFormGrid"><div class="FilesFormField"><label class="uk-form-label" for="files-days">'.$this->_('Expires after').'</label><div class="FilesInputSuffix"><input class="uk-input" id="files-days" type="number" name="days" min="1" max="'.$maximum.'" value="'.$default.'" required><span>'.$this->_('days').'</span></div><small>'.sprintf($this->_('Maximum %d days'),$maximum).'</small></div><div class="FilesFormField"><label class="uk-form-label" for="files-limit">'.$this->_('Download limit').'</label><input class="uk-input" id="files-limit" type="number" name="max_downloads" min="0" value="0"><small>'.$this->_('Use 0 for unlimited downloads.').'</small></div></div><div class="FilesFormField"><label class="uk-form-label" for="files-password">'.$this->_('Password protection').'<span class="FilesOptional">'.$this->_('Optional').'</span></label><input class="uk-input" id="files-password" type="password" name="password" minlength="8" autocomplete="new-password" placeholder="'.$this->_('At least 8 characters').'"><small>'.$this->_('The password is stored as a secure hash and cannot be recovered.').'</small></div>'.$this->csrfFields().'<button class="uk-button uk-button-primary FilesCreateShareButton" type="submit"><i class="fa fa-link" aria-hidden="true"></i><span>'.$this->_('Create sharing link').'</span></button></form></section>'; }

	private function shareTable(array $shares,int $itemId): string { $activeCount=0;foreach($shares as $share){$expired=!empty($share['expires_at'])&&strtotime((string)$share['expires_at'])<=time();$limited=(int)$share['max_downloads']>0&&(int)$share['download_count']>=(int)$share['max_downloads'];if(empty($share['revoked_at'])&&!$expired&&!$limited)$activeCount++;}$out='<section class="FilesTable FilesSharesTable"><header><div><p class="FilesEyebrow">'.$this->_('Access history').'</p><h2>'.$this->_('Links and recipients').'</h2></div><span class="FilesShareCount"><strong>'.$activeCount.'</strong>'.$this->_('active').'</span></header>';if(!$shares)return$out.'<div class="FilesEmpty FilesEmpty--compact"><span class="FilesEmptyIcon"><i class="fa fa-link" aria-hidden="true"></i></span><h3>'.$this->_('No sharing links yet').'</h3><p>'.$this->_('Create the first controlled link using the form above.').'</p></div></section>';$out.='<div class="FilesTableScroll FilesShareHistory"><table class="uk-table uk-table-divider uk-table-middle"><thead><tr><th>'.$this->_('Recipient').'</th><th>'.$this->_('Protection').'</th><th>'.$this->_('Downloads').'</th><th>'.$this->_('Expires').'</th><th>'.$this->_('Status').'</th><th class="FilesActionsColumn">'.$this->_('Action').'</th></tr></thead><tbody>';foreach($shares as $share){$expired=!empty($share['expires_at'])&&strtotime((string)$share['expires_at'])<=time();$limited=(int)$share['max_downloads']>0&&(int)$share['download_count']>=(int)$share['max_downloads'];$active=empty($share['revoked_at'])&&!$expired&&!$limited;$userShare=(int)$share['recipient_user_id']>0;$recipient=$userShare?((string)$share['recipient_name'].' · '.(string)$share['recipient_email']):$this->_('Anyone with the link');$recipientType=$userShare?$this->_('ProcessWire user'):$this->_('Public secret link');$status=!empty($share['revoked_at'])?$this->_('Revoked'):($expired?$this->_('Expired'):($limited?$this->_('Limit reached'):$this->_('Active')));$state=$active?'active':($limited||$expired?'warning':'neutral');$protection=!empty($share['password_protected'])?'<span class="FilesProtection"><i class="fa fa-lock" aria-hidden="true"></i>'.$this->_('Password').'</span>':'<span class="FilesProtection"><i class="fa fa-key" aria-hidden="true"></i>'.$this->_('Secret URL').'</span>';$downloads=(int)$share['download_count'].' / '.((int)$share['max_downloads']>0?(int)$share['max_downloads']:$this->_('Unlimited'));$action=$active?'<form method="post" action="'.$this->e($this->wire('page')->url.'revoke/').'" onsubmit="return confirm(\''.$this->e($this->_('Revoke this sharing link?')).'\')"><input type="hidden" name="id" value="'.(int)$share['id'].'"><input type="hidden" name="item_id" value="'.$itemId.'">'.$this->csrfFields().'<button class="FilesRevokeButton" type="submit"><i class="fa fa-ban" aria-hidden="true"></i><span>'.$this->_('Revoke').'</span></button></form>':'<span class="FilesMuted">—</span>';$out.='<tr><td data-label="'.$this->_('Recipient').'"><span class="FilesRecipient"><i class="fa fa-'.($userShare?'user':'globe').'" aria-hidden="true"></i><span><strong>'.$this->e($recipient).'</strong><small>'.$recipientType.'</small></span></span></td><td data-label="'.$this->_('Protection').'">'.$protection.'</td><td data-label="'.$this->_('Downloads').'">'.$downloads.'</td><td data-label="'.$this->_('Expires').'"><time datetime="'.$this->e((string)$share['expires_at']).'">'.$this->e($this->formatDate((string)$share['expires_at'])).'</time></td><td data-label="'.$this->_('Status').'"><span class="FilesBadge" data-state="'.$state.'">'.$this->e($status).'</span></td><td data-label="'.$this->_('Action').'">'.$action.'</td></tr>';}return$out.'</tbody></table></div></section>'; }

	private function sharedRootTable(array $items): string { if(!$items)return'<section class="FilesEmpty"><i class="fa fa-share-alt"></i><h3>'.$this->_('Nothing shared with you').'</h3><p>'.$this->_('User-specific shares will appear here.').'</p></section>';$out='<section class="FilesTable"><div class="uk-overflow-auto"><table class="uk-table uk-table-divider uk-table-hover uk-table-middle"><thead><tr><th>'.$this->_('Name').'</th><th>'.$this->_('Type').'</th><th>'.$this->_('Expires').'</th><th>'.$this->_('Access').'</th></tr></thead><tbody>';foreach($items as $item)$out.='<tr><td><a class="FilesItemName" href="?id='.(int)$item['share_id'].'"><span><i class="fa fa-'.($item['kind']==='folder'?'folder':'file-o').'"></i></span><strong>'.$this->e($item['display_name']).'</strong></a></td><td>'.$this->e(ucfirst($item['kind'])).'</td><td>'.$this->e($item['expires_at']).'</td><td>'.$this->_('Read-only').'</td></tr>';return$out.'</tbody></table></div></section>'; }
	private function sharedContentTable(array $content): string { $share=$content['share'];$target=$content['target'];$items=$content['items'];$canDownload=$this->service()->canDownload();$out='<section class="FilesTable"><header><div><p class="uk-text-meta uk-text-uppercase uk-margin-remove">'.$this->_('Shared folder').'</p><h2>'.$this->e($target['display_name']).'</h2></div></header><div class="uk-overflow-auto"><table class="uk-table uk-table-divider uk-table-middle"><thead><tr><th>'.$this->_('Name').'</th><th>'.$this->_('Size').'</th><th>'.$this->_('Action').'</th></tr></thead><tbody>';foreach($items as $item){if($item['kind']!=='file')continue;$action=$canDownload?'<a class="uk-button uk-button-default uk-button-small" href="'.$this->e($this->wire('page')->url.'shared-download/?share='.(int)$share['id'].'&file='.(int)$item['id']).'">'.$this->_('Download').'</a>':'<span class="FilesMuted">'.$this->_('No download permission').'</span>';$out.='<tr><td>'.$this->e($item['display_name']).'</td><td>'.$this->e($this->formatBytes((int)$item['size_bytes'])).'</td><td>'.$action.'</td></tr>';}return$out.'</tbody></table></div></section>'; }

	private function csrfFields(): string { $csrf=$this->wire('session')->CSRF;return'<input type="hidden" name="'.$this->e($csrf->getTokenName()).'" value="'.$this->e($csrf->getTokenValue()).'">'; }
	private function jsonResponse(array $payload,int $status=200): never { while(ob_get_level())ob_end_clean();http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: private, no-store, max-age=0');header('X-Content-Type-Options: nosniff');echo json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit; }
	private function viewUrl(int $folderId,string $view,string $q='',string $type=''): string { $params=['folder'=>$folderId];if($view==='grid')$params['view']='grid';if($q!=='')$params['q']=$q;if($type!=='')$params['type']=$type;return$this->wire('page')->url.'?'.http_build_query($params,'','&',PHP_QUERY_RFC3986); }
	private function typeOptions(string $selected): string { $extensions=preg_split('/[\s,]+/',strtolower(trim((string)$this->service()->allowed_extensions)),-1,PREG_SPLIT_NO_EMPTY)?:[];$extensions=array_values(array_unique($extensions));sort($extensions,SORT_NATURAL);$out='<option value="">'.$this->_('All file types').'</option>';foreach($extensions as $extension)$out.='<option value="'.$this->e($extension).'"'.($selected===$extension?' selected':'').'>'.strtoupper($this->e($extension)).'</option>';return$out; }
	private function formatDate(string $value): string { $time=strtotime($value);return$time?date('M j, Y · H:i',$time):$value; }
	private function formatBytes(int $bytes): string { $units=['B','KB','MB','GB','TB'];$value=max(0,$bytes);$unit=0;while($value>=1024&&$unit<count($units)-1){$value/=1024;$unit++;}return($unit===0?(string)(int)$value:number_format($value,$value>=10?1:2)).' '.$units[$unit]; }
	private function workspace(string $content): string { return'<div class="pw-wrap pw-module-workspace FilesAdmin">'.$content.'</div>'; }
	private function e($value): string { return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
}
